// 1. Hardware Register Access (MMIO)
#define REG_ADDR 0xDEADBEEF
// The data at this address changes externally
volatile uint32_t * const STATUS_REG = (volatile uint32_t*)REG_ADDR;

uint32_t status = *STATUS_REG; // Forces read from memory
status = *STATUS_REG;          // Forces another read (no caching)

// 2. Interrupt Flag / Shared State
volatile bool interrupt_flag = false;

void isr_handler() {
    interrupt_flag = true;
}

// Compiler cannot optimize this loop into 'while(true)'
void main_loop() {
    while (!interrupt_flag) {}
}

// 3. Pointer Placement Distinction
int value;
volatile int *p1;         // Data is volatile, pointer is not
int * volatile p2;        // Pointer is volatile, data is not
volatile int * volatile p3; // Both are volatile
